select o.out_id, o.out_no, o.out_type, o.receiver, o.class_id, o.out_time, o.operator, o.remark, o.status, o.create_by, o.create_time, o.update_by, o.update_time, o.del_flag, c.class_name, c.grade, p.print_id, p.print_name, coalesce(u_dept.dept_name, '') as dept from edu_stock_out o left join edu_class c on o.class_id = c.class_id left join ( select out_id, min(print_id) as print_id, min(print_name) as print_name from edu_print_record where del_flag = '0' and out_id is not null group by out_id ) p on o.out_id = p.out_id left join ( select u.nick_name, min(d.dept_name) as dept_name from sys_user u inner join sys_dept d on u.dept_id = d.dept_id where u.del_flag = '0' group by u.nick_name ) u_dept on o.receiver = u_dept.nick_name WHERE o.del_flag = '0' order by o.out_id desc;
